function Cylinder({ size, c, styles }: { size: number; c: Palette; styles: ReturnType<typeof makeStyles> }) {
  return <View style={styles.cylinder}><View style={styles.cylinderValve}/><View style={styles.cylinderNeck}/><View style={styles.cylinderBody}><Text style={styles.cylinderNumber}>{size}</Text><Text style={styles.cylinderKg}>KG</Text></View><View style={styles.cylinderFoot}/></View>;
}
function Step({ number, title, detail, c, styles }: { number: string; title: string; detail: string; c: Palette; styles: ReturnType<typeof makeStyles> }) {
  return <View style={styles.step}><Text style={styles.stepNumber}>{number}</Text><View><Text style={styles.productSize}>{title}</Text><Text style={styles.productDetail}>{detail}</Text></View></View>;
}
function OrdersScreen({ orders, onShop, c, styles }: { orders: CustomerOrder[]; onShop: () => void; c: Palette; styles: ReturnType<typeof makeStyles> }) {
  return <View><Text style={styles.titleSmall}>Orders</Text><Text style={styles.screenIntro}>Order progress and exchange details in one place.</Text>{orders.length ? orders.map((order) => <View key={order.id} style={styles.customerOrderCard}><View style={styles.customerOrderHeading}><View><Text style={styles.eyebrow}>ORDER #{order.order_number}</Text><Text style={styles.productDetail}>{new Date(order.created_at).toLocaleDateString("en-NG", { dateStyle: "medium" })}</Text></View><Text style={styles.customerOrderAmount}>₦{(Number(order.total_kobo) / 100).toLocaleString("en-NG")}</Text></View><Text style={styles.productSize}>{order.order_items?.map((item) => `${item.weight_kg_snapshot} kg × ${item.quantity}`).join(" · ")}</Text><Text style={styles.productDetail}>{order.delivery_address_snapshot}</Text><View style={styles.customerOrderStatuses}><Text style={styles.productDetail}>{order.delivery_status.replaceAll("_", " ")}</Text><Text style={[styles.customerOrderPayment, order.payment_status === "paid" && styles.customerOrderPaid]}>{order.payment_status.replaceAll("_", " ")}</Text></View></View>) : <View style={styles.ordersPanel}><View style={styles.ordersTop}><View style={styles.emptyIcon}><AppIcon name="orders" size={23} color={c.primary}/></View><Text style={styles.eyebrow}>NO ORDERS YET</Text><Text style={styles.ordersTitle}>Your deliveries will appear here.</Text><Text style={styles.productDetail}>When you place an order, payment and delivery updates will appear here.</Text><Pressable style={styles.primaryButton} onPress={onShop}><Text style={styles.primaryText}>Start an order</Text><AppIcon name="arrow" size={18} color="#fff"/></Pressable></View><View style={styles.orderSteps}><Text style={styles.eyebrow}>WHAT YOU’LL BE ABLE TO FOLLOW</Text><Step number="01" title="Order confirmed" detail="Mobsol confirms your order and delivery details." c={c} styles={styles}/><Step number="02" title="Preparing your exchange" detail="Your full cylinder is prepared for dispatch." c={c} styles={styles}/><Step number="03" title="Rider on the way" detail="Track delivery and exchange at your door." c={c} styles={styles}/></View></View>}</View>;
}
function SupportScreen({ onShop, onSetLocation, openFaq, setOpenFaq, c, styles }: { onShop: () => void; onSetLocation: () => void; openFaq: number | null; setOpenFaq: (value: number | null) => void; c: Palette; styles: ReturnType<typeof makeStyles> }) {
  const faqs = [
    ["How does the cylinder exchange work?", "Choose a full Mobsol cylinder. At delivery, the rider brings it to you and collects your empty Mobsol cylinder. Mobsol does not refill cylinders at home."],
    ["Can I order for someone else?", "Yes. Choose Someone else during checkout and enter their name, phone number, and Abuja delivery address. You can choose who is expected to pay."],
    ["How do I know if my area is covered?", "Enter your delivery address and Mobsol will check it against active service zones. Live zone verification is not connected yet."],
    ["When will I see the price?", "The current gas rate and each cylinder's gas price are shown on the home page and in your cart. Delivery is added after your service area is checked."],
  ];
  return <View><Text style={styles.titleSmall}>How can we help?</Text><Text style={styles.screenIntro}>Quick answers about your cylinder exchange and delivery.</Text><View style={styles.supportActions}><Pressable style={styles.supportAction} onPress={onShop}><AppIcon name="plus" size={19} color={c.primary}/><View style={{flex:1}}><Text style={styles.supportActionTitle}>Start an order</Text><Text style={styles.productDetail}>Choose a Mobsol cylinder</Text></View><AppIcon name="arrow" size={16} color={c.muted}/></Pressable><Pressable style={styles.supportAction} onPress={onSetLocation}><AppIcon name="location" size={19} color={c.primary}/><View style={{flex:1}}><Text style={styles.supportActionTitle}>Check your location</Text><Text style={styles.productDetail}>See if delivery is available</Text></View><AppIcon name="arrow" size={16} color={c.muted}/></Pressable></View><Text style={styles.eyebrow}>COMMON QUESTIONS</Text>{faqs.map(([question, answer], index) => <View key={question} style={styles.faq}><Pressable style={styles.faqQuestion} onPress={() => setOpenFaq(openFaq === index ? null : index)}><Text style={styles.faqQuestionText}>{question}</Text>{openFaq === index ? <Text style={styles.faqPlus}>−</Text> : <AppIcon name="plus" size={17} color={c.text2}/>}</Pressable>{openFaq === index && <Text style={styles.faqAnswer}>{answer}</Text>}</View>)}<View style={styles.supportCard}><AppIcon name="support" size={19} color={c.primary}/><Text style={styles.supportTitle}>Need more help?</Text><Text style={styles.productDetail}>Mobsol’s phone and chat support details will appear here when the customer support channels are configured.</Text></View></View>;
}
function SupportCard({ title, text, icon, c, styles }: { title: string; text: string; icon: IconName; c: Palette; styles: ReturnType<typeof makeStyles> }) {
  return <View style={styles.supportCard}><AppIcon name={icon} size={19} color={c.primary}/><Text style={styles.supportTitle}>{title}</Text><Text style={styles.productDetail}>{text}</Text></View>;
}
function EmptyScreen({ title, text, action, onPress, c, styles }: { title: string; text: string; action: string; onPress: () => void; c: Palette; styles: ReturnType<typeof makeStyles> }) {
  return <View style={styles.empty}><Text style={styles.eyebrow}>MOBSOL GAS · ABUJA</Text><Text style={styles.titleSmall}>{title}</Text><Text style={styles.copy}>{text}</Text><Pressable style={styles.primaryButton} onPress={onPress}><Text style={styles.primaryText}>{action}</Text><Text style={styles.primaryArrow}>→</Text></Pressable></View>;
}

